    return to==='C'?c:to==='F'?c*9/5+32:c+273.15;}
  return v*T[from]/T[to];}
var r=conv(DATA.value,DATA.from,DATA.to);
console.log(DATA.value+' '+DATA.from+' = '+r.toFixed(6)+' '+DATA.to+'  ('+DATA.label+')');
})();

